#define u_resolution iResolution.xy
#define u_mouse iMouse.xy
#define u_time iTime

#define END 200.0
#define MAX_STEPS 200
#define SENSETIVE_POINT 0.001
#define SURFACE_DIST 0.1
#define PI 3.1415926

float box( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float torus( vec3 p, vec2 t )
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

float scDist(vec3 p)
{
    float boxDist = box(p - vec3(0,1,6),vec3(0.5,0.5,0.5));
	float dO = boxDist;
	float boxDist2 = torus(p - vec3(2,1,4),vec2(0.5,0.3));
    dO = min(dO,boxDist2);
	float boxDist3 = box(p - vec3(4,1,2),vec3(0.5,0.5,0.5));
	dO = min(dO,boxDist3);
	float boxDist4 = torus(p - vec3(6,1,0),vec2(0.5,0.3));
	dO = min(dO, boxDist4);
    float planeDist = p.y;
    dO = min(dO, planeDist);

    return dO;
}

float rayMarch(vec3 pos, vec3 rotate)
{
	float depth = 0.0;
	for (int i = 0; i < MAX_STEPS; ++i) {
		vec3 p = pos + rotate * depth;
		float dist = scDist(p);
		depth += dist;
		if (depth > END || dist < SENSETIVE_POINT) {
			break;
		}
	}
	return depth;
}

vec3 normals(vec3 p)
{
    float d = scDist(p);
    vec2 e = vec2(0.01,0.0);
    vec3 n = d - vec3(
    scDist(p-e.xyy),
    scDist(p-e.yxy),
    scDist(p-e.yyx));

    return normalize(n);
}

vec3 light(vec3 lightPos, vec3 p, vec3 rd, vec3 col)
{ 
    vec3 l = normalize(lightPos - p);
    vec3 n = normals(p);
	vec3 v = -rd;
	vec3 r = reflect(-l, n);

	vec3 specColor = vec3(0.5);
	vec3 specular = specColor * pow(clamp(dot(r,v),0.0,1.0),10.0);
    vec3 dife = col * clamp(dot(l,n),0.0,1.0);
	vec3 amb = col * vec3(0.05);

	float d = rayMarch(p + n * SURFACE_DIST * 2.0, normalize(lightPos - p)); 

    if(d < length(lightPos - p)){
		return amb;
	}
	else
	{
		return dife + amb + specular;
	}
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
	vec2 uv = (fragCoord.xy-0.5*u_resolution.xy)/min(u_resolution.x, u_resolution.y);

	float r = 5.0;
    float theta = 2.0 * PI * (u_mouse.x / u_resolution.x - 0.25);
    float phi = 0.5 * PI * (u_mouse.y / u_resolution.y + 0.0001);

    vec3 ta = vec3(3,1,3);
    vec3 ro = ta + r * vec3(sin(phi) * cos(theta), cos(phi), sin(phi) * sin(theta));

    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(ww, vec3(0.0,1.0,0.0)));
    vec3 vv = normalize(cross(uu, ww));

    vec3 rd = normalize(vec3(uv.x * uu + uv.y * vv + 1.0 * ww));

	float dep = rayMarch(ro,rd);

    vec3 p = ro + rd * dep;
    vec3 dif = light(vec3(3.0,3.0,3.0), p, rd, vec3(0.9,0.0,0.0));
    dep *= 0.2;
    vec3 color = dif;

	color = pow(color, vec3(0.4545));

    fragColor = vec4(color,1.0);
}
